        kind: "create_order",
        money: price,
        intent: "CAPTURE",
        customId: intentId,
      });
      let created: ProviderResource | null = null;
      for (let attempt = 0; attempt < 2 && !created; attempt += 1) {
        try {
          const receipt = await provider.execute(create);
          created = receipt.resources.find((resource) => resource.kind === "order") ?? null;
          if (!created) {
            return await finish("failed", "Order creation returned no order; nothing was approved or captured.");
          }
        } catch (error) {
          const failure = classify(error);
          await emit({
            lane: "application",
            kind: "order.create_failed",
            title: "Create order did not succeed",
            detail: failure.message,
            requestId: create.providerRequestId,
            facts: { outcome: failure.outcome, httpStatus: failure.httpStatus, attempt },
          });
          // Only an unanswered create is repeated, once, under the same PayPal-Request-Id.
          if (failure.outcome !== "unknown" || attempt === 1) {
            return await finish("failed", "No order could be created; nothing was approved or captured.", {
              unknown: false,
            });
          }
        }
      }
      if (!created) return await finish("failed", "No order could be created.", { unknown: false });
      if (
        (created.money && !sameMoney(created.money, price)) ||
        (created.customId !== null && created.customId !== undefined && created.customId !== intentId)
      ) {
        return await finish("failed", "The created order does not match this purchase; it was not approved.", {
          unknown: false,
        });
      }
      orderId = created.id;
      approved = created.status === "APPROVED";
      state.orderIds = [...state.orderIds, orderId];
      await store.setTargetState(runId, state);
      await emit({
        lane: "application",
        kind: "order.created",
        title: "Order created",
        detail: "One order for the exact price.",
        identity: "stable",
        resourceId: orderId,
        requestId: create.providerRequestId,
      });
    }

    if (!approved) {
      try {
        await transport.approve(orderId);
      } catch (error) {
        return await finish("failed", `The buyer did not approve the order: ${classify(error).message}`, {
          unknown: false,
        });
      }
    }

    // Approval is rechecked at the last moment before money can move.
    if (await revoked()) {
      return await finish("failed", "The buyer's approval was withdrawn; nothing was captured.", { unknown: false });
    }

    const capture = command("capture", { kind: "capture_order", money: price, orderId });
    let failure: ReturnType<typeof classify> | null = null;
    captureSent = true;
    try {
      const receipt = await provider.execute(capture);
      const observed = pickCapture(receipt.resources);
      if (observed) return await settle(observed);
    } catch (error) {
      failure = classify(error);
      await emit({
        lane: "application",
        kind: "capture.unconfirmed",
        title: "Capture was not confirmed",
        detail: failure.message,
        resourceId: orderId,
        requestId: capture.providerRequestId,
        facts: { outcome: failure.outcome, httpStatus: failure.httpStatus },
      });
      if (failure.outcome === "not_sent") {
        return await finish("failed", "The capture request was never sent.", { unknown: false });
      }
    }

    // The capture answer is missing, unreadable or an error. Read the order; never send the capture again here.
    try {
      const seen = await provider.read("order", orderId);
      const observed = pickCapture(seen);
      if (observed) return await settle(observed);
      if (failure?.outcome === "rejected") {
        return await finish("failed", "PayPal refused the capture and the order shows no capture.", {
          unknown: false,
        });
      }
    } catch {
      if (failure?.outcome === "rejected" && [400, 401, 403, 404].includes(failure.httpStatus)) {
        return await finish("failed", "PayPal refused the capture.", { unknown: false });
      }
    }
    return await finish("checking", "The capture outcome is not known yet; the book is withheld.", { unknown: true });
  } catch (error) {
    const message = classify(error).message;
    try {
      return await finish(
        captureSent ? "checking" : "failed",
        captureSent ? `Unexpected error after capture was sent: ${message}` : `Unexpected error before capture: ${message}`,
        { unknown: captureSent },
      );
    } catch {
      return {
        status: captureSent ? "checking" : "failed",
        orderId,
        captureId: state.lastCaptureId,
        fulfilled: state.fulfillmentCount > 0,
        reason: message,
      };
    }
  }
}

