import { createHash, randomUUID } from "node:crypto";
import { ProviderError, SandboxPayPalProvider, assertMoney, payloadHash } from "@fracture/paypal-core";
import type { MinorMoney, PaymentAction, PaymentCommand, ProviderResource } from "@fracture/paypal-core";
import type { ApplicationEvent, BrambleContext, TargetState } from "@fracture/source-target";

const PAYPAL_BASE_URL = "https://api-m.sandbox.paypal.com";

export interface CheckoutResult {
  status: TargetState["status"];
  orderId: string | null;
  captureId: string | null;
  fulfilled: boolean;
  reason: string;
}

type Outcome = "unknown" | "rejected" | "not_sent";

/** One in-flight checkout per purchase in this process; the database constraint covers the rest. */
const inFlight = new Map<string, Promise<CheckoutResult>>();

export async function checkout(context: BrambleContext): Promise<unknown> {
  const key = `${context.run.id}\u0000${context.run.businessIntentId}`;
  const existing = inFlight.get(key);
  if (existing) return existing;
  const work = runCheckout(context).finally(() => {
    if (inFlight.get(key) === work) inFlight.delete(key);
  });
  inFlight.set(key, work);
  return work;
}

const digest = (value: string): string => createHash("sha256").update(value).digest("hex");

const sameMoney = (a: MinorMoney, b: MinorMoney): boolean =>
  a.currency.toUpperCase() === b.currency.toUpperCase() && a.minor === b.minor;

function classify(error: unknown): { outcome: Outcome; httpStatus: number; message: string } {
  if (error instanceof ProviderError) {
    return { outcome: error.outcome, httpStatus: error.httpStatus, message: error.message };
  }
  const message = error instanceof Error ? error.message : String(error);
  if (typeof error === "object" && error !== null) {
    const candidate = error as { outcome?: unknown; httpStatus?: unknown };
    if (candidate.outcome === "rejected" || candidate.outcome === "not_sent" || candidate.outcome === "unknown") {
      return {
        outcome: candidate.outcome,
        httpStatus: typeof candidate.httpStatus === "number" ? candidate.httpStatus : 0,
        message,
      };
    }
  }
  return { outcome: "unknown", httpStatus: 0, message };
}

function pickCapture(resources: readonly ProviderResource[]): ProviderResource | null {
  const captures = resources.filter((resource) => resource.kind === "capture");
  return captures.find((capture) => capture.status === "COMPLETED") ?? captures[0] ?? null;
}

async function runCheckout(context: BrambleContext): Promise<CheckoutResult> {
  const { run, store, transport } = context;
  const runId = run.id;
  const intentId = run.businessIntentId;
  const price: MinorMoney = { currency: run.currency, minor: run.amountMinor };
  const entitlementKey = `digital_book:${intentId}`;

  const emit = async (event: ApplicationEvent): Promise<void> => {
    try {
      await store.emit(runId, event);
    } catch {
      // The trace is best effort; it never decides the purchase.
    }
  };

  const state: TargetState = await store.targetState(runId, intentId);
  let orderId: string | null = state.orderIds.at(-1) ?? null;
  let captureSent = false;

  const finish = async (
    status: TargetState["status"],
    reason: string,
    patch: Partial<TargetState> = {},
  ): Promise<CheckoutResult> => {
    Object.assign(state, patch, { status });
    await store.setTargetState(runId, state);
    await emit({
      lane: "customer",
      kind: `checkout.${status}`,
      title: `Phone shows ${status}`,
      detail: reason,
      identity: "stable",
      ...(orderId ? { resourceId: orderId } : {}),
      facts: { status, captureId: state.lastCaptureId, fulfillmentCount: state.fulfillmentCount },
    });
    return {
      status,
      orderId,
      captureId: state.lastCaptureId,
      fulfilled: state.fulfillmentCount > 0,
      reason,
    };
  };

  const fulfillmentRows = async (): Promise<{ capture_id: string | null }[]> => {
    const found = await store.db.query<{ capture_id: string | null }>(
      "SELECT capture_id FROM lab_fulfillments WHERE run_id=$1 AND entitlement_key=$2",
      [runId, entitlementKey],
    );
    return found.rows;
  };

  const revoked = async (): Promise<boolean> => {
    try {
      const faults = await store.db.query<{ fault_key: string }>(
        "SELECT fault_key FROM lab_faults WHERE run_id=$1",
        [runId],
      );
      return faults.rows.some((row) => row.fault_key === "approval-revoked");
    } catch {
      // Approval that cannot be confirmed is not approval.
      return true;
    }
  };

  try {
    // Already delivered: never charge or deliver again.
    const delivered = await fulfillmentRows();
    const first = delivered[0];
    if (first) {
      return await finish("paid", "The book was already delivered for this purchase.", {
        lastCaptureId: first.capture_id ?? state.lastCaptureId,
        fulfillmentCount: delivered.length,
        unknown: false,
      });
    }

    try {
      assertMoney(price);
    } catch (error) {
      return await finish("failed", `Invalid price, nothing was sent: ${classify(error).message}`);
    }

    const provider = new SandboxPayPalProvider(
      {
        environment: "sandbox",
        baseUrl: PAYPAL_BASE_URL,
        // The Sample provider model has no real credentials; the run id stands in for both.
        clientId: runId,
        clientSecret: runId,
        isolatedProject: "bramble-books-sample",
      },
      transport.fetch,
    );

    const command = (step: "create" | "capture", action: PaymentAction): PaymentCommand => {
      // Stable per purchase and step, so a repeated submit names the same provider request.
      const identity = digest(`bramble:${runId}:${intentId}:${step}`);
      const hash = payloadHash(action);
      return {
        scope: { tenantId: "bramble-books", projectId: "bramble-books-sample" },
        operationId: `bramble-${step}-${identity.slice(0, 32)}`,
        businessKey: `${intentId}:${step}`,
        intentId,
        providerRequestId: `bramble-${step}-${identity.slice(0, 40)}`,
        payloadHash: hash,
        action,
        approval: {
          id: `customer-submit:${intentId}`,
          version: 1,
          digest: hash,
          expiresAt: new Date(Date.now() + 15 * 60 * 1000).toISOString(),
        },
      };
    };

    const deliver = async (captureId: string): Promise<CheckoutResult> => {
      let rows = await fulfillmentRows();
      if (rows.length === 0) {
        try {
          await store.db.query(
            "INSERT INTO lab_fulfillments(id,run_id,intent_id,capture_id,entitlement_key,document) VALUES($1,$2,$3,$4,$5,$6)",
            [
              randomUUID(),
              runId,
              intentId,
              captureId,
              entitlementKey,
              JSON.stringify({ source: "sample", kind: "digital_book", captureId }),
            ],
          );
        } catch (error) {
          // UNIQUE(run_id, entitlement_key): another submit delivered first. Anything else is rethrown below.
          rows = await fulfillmentRows();
          if (rows.length === 0) throw error;
        }
        rows = await fulfillmentRows();
      }
      await emit({
        lane: "application",
        kind: "fulfillment.delivered",
        title: "Book delivered",
        detail: "One entitlement row exists for this purchase.",
        identity: "stable",
        resourceId: captureId,
        facts: { entitlementKey, rows: rows.length },
      });
      return finish("paid", "Captured for the exact price; one book delivered.", {
        lastCaptureId: rows[0]?.capture_id ?? captureId,
        fulfillmentCount: rows.length,
        unknown: false,
      });
    };

    /** Decide the purchase from an observed capture. Only a completed capture of the exact price delivers. */
    const settle = async (capture: ProviderResource): Promise<CheckoutResult> => {
      if (capture.status === "COMPLETED") {
        let money = capture.money;
        if (!money && orderId) {
          try {
            const seen = await provider.read("order", orderId);
            money =
              seen.find((resource) => resource.kind === "capture" && resource.id === capture.id)?.money ??
              seen.find((resource) => resource.kind === "order")?.money ??
              null;
          } catch {
            money = null;
          }
        }
        if (money && !sameMoney(money, price)) {
          await emit({
            lane: "application",
            kind: "capture.amount_mismatch",
            title: "Captured amount differs from the price",
            detail: "The book is withheld until the payment is reviewed.",
            resourceId: capture.id,
            facts: { expected: price, observed: money },
          });
          return finish("checking", "A capture exists but not for the exact price; nothing delivered.", {
            lastCaptureId: capture.id,
            unknown: true,
          });
        }
        return deliver(capture.id);
      }
      if (capture.status === "DECLINED" || capture.status === "FAILED") {
        return finish("failed", `The capture was ${capture.status}.`, { lastCaptureId: capture.id, unknown: false });
      }
      return finish("checking", `The capture is ${capture.status}; the money has not arrived yet.`, {
        lastCaptureId: capture.id,
        unknown: false,
      });
    };

    state.attempt += 1;
    let approved = false;

    // A known order is read before anything is written: an earlier submit may already have been paid.
    if (orderId) {
      let seen: ProviderResource[];
      try {
        seen = await provider.read("order", orderId);
      } catch (error) {
        return await finish("checking", `The existing order could not be read: ${classify(error).message}`, {
          unknown: true,
        });
      }
      const capture = pickCapture(seen);
      if (capture) return await settle(capture);
      const order = seen.find((resource) => resource.kind === "order");
      if (order?.status === "VOIDED") return await finish("failed", "The order was voided.", { unknown: false });
      approved = order?.status === "APPROVED";
    }

    if (await revoked()) {
      return await finish("failed", "The buyer's approval was withdrawn; nothing was captured.", { unknown: false });
    }

    Object.assign(state, { status: "processing" });
    await store.setTargetState(runId, state);

    if (!orderId) {
      const create = command("create", {
        kind: "create_order",
        money: price,
        intent: "CAPTURE",
        customId: intentId,
      });
      let created: ProviderResource | null = null;
      for (let attempt = 0; attempt < 2 && !created; attempt += 1) {
        try {
          const receipt = await provider.execute(create);
          created = receipt.resources.find((resource) => resource.kind === "order") ?? null;
          if (!created) {
            return await finish("failed", "Order creation returned no order; nothing was approved or captured.");
          }
        } catch (error) {
          const failure = classify(error);
          await emit({
            lane: "application",
            kind: "order.create_failed",
            title: "Create order did not succeed",
            detail: failure.message,
            requestId: create.providerRequestId,
            facts: { outcome: failure.outcome, httpStatus: failure.httpStatus, attempt },
          });
          // Only an unanswered create is repeated, once, under the same PayPal-Request-Id.
          if (failure.outcome !== "unknown" || attempt === 1) {
            return await finish("failed", "No order could be created; nothing was approved or captured.", {
              unknown: false,
            });
          }
        }
      }
      if (!created) return await finish("failed", "No order could be created.", { unknown: false });
      if (
        (created.money && !sameMoney(created.money, price)) ||
        (created.customId !== null && created.customId !== undefined && created.customId !== intentId)
      ) {
        return await finish("failed", "The created order does not match this purchase; it was not approved.", {
          unknown: false,
        });
      }
      orderId = created.id;
      approved = created.status === "APPROVED";
      state.orderIds = [...state.orderIds, orderId];
      await store.setTargetState(runId, state);
      await emit({
        lane: "application",
        kind: "order.created",
        title: "Order created",
        detail: "One order for the exact price.",
        identity: "stable",
        resourceId: orderId,
        requestId: create.providerRequestId,
      });
    }

    if (!approved) {
      try {
        await transport.approve(orderId);
      } catch (error) {
        return await finish("failed", `The buyer did not approve the order: ${classify(error).message}`, {
          unknown: false,
        });
      }
    }

    // Approval is rechecked at the last moment before money can move.
    if (await revoked()) {
      return await finish("failed", "The buyer's approval was withdrawn; nothing was captured.", { unknown: false });
    }

    const capture = command("capture", { kind: "capture_order", money: price, orderId });
    let failure: ReturnType<typeof classify> | null = null;
    captureSent = true;
    try {
      const receipt = await provider.execute(capture);
      const observed = pickCapture(receipt.resources);
      if (observed) return await settle(observed);
    } catch (error) {
      failure = classify(error);
      await emit({
        lane: "application",
        kind: "capture.unconfirmed",
        title: "Capture was not confirmed",
        detail: failure.message,
        resourceId: orderId,
        requestId: capture.providerRequestId,
        facts: { outcome: failure.outcome, httpStatus: failure.httpStatus },
      });
      if (failure.outcome === "not_sent") {
        return await finish("failed", "The capture request was never sent.", { unknown: false });
      }
    }

    // The capture answer is missing, unreadable or an error. Read the order; never send the capture again here.
    try {
      const seen = await provider.read("order", orderId);
      const observed = pickCapture(seen);
      if (observed) return await settle(observed);
      if (failure?.outcome === "rejected") {
        return await finish("failed", "PayPal refused the capture and the order shows no capture.", {
          unknown: false,
        });
      }
    } catch {
      if (failure?.outcome === "rejected" && [400, 401, 403, 404].includes(failure.httpStatus)) {
        return await finish("failed", "PayPal refused the capture.", { unknown: false });
      }
    }
    return await finish("checking", "The capture outcome is not known yet; the book is withheld.", { unknown: true });
  } catch (error) {
    const message = classify(error).message;
    try {
      return await finish(
        captureSent ? "checking" : "failed",
        captureSent ? `Unexpected error after capture was sent: ${message}` : `Unexpected error before capture: ${message}`,
        { unknown: captureSent },
      );
    } catch {
      return {
        status: captureSent ? "checking" : "failed",
        orderId,
        captureId: state.lastCaptureId,
        fulfilled: state.fulfillmentCount > 0,
        reason: message,
      };
    }
  }
}

