interface WireMoney {
  currency_code?: unknown;
  value?: unknown;
}
interface WireCapture {
  id?: unknown;
  status?: unknown;
  amount?: unknown;
}
interface WirePayments {
  captures?: unknown;
}
interface WireUnit {
  amount?: unknown;
  custom_id?: unknown;
  payments?: unknown;
}
interface WireOrder {
  id?: unknown;
  status?: unknown;
  purchase_units?: unknown;
